from dataclasses import dataclass


@dataclass
class Task:
    id: int
    text: str
    done: bool = False

edits.newText:
def ordered(tasks):
    priority_map = {"high": 0, "normal": 1, "low": 2}
    return sorted(tasks, key=lambda t: (priority_map.get(t.priority, 1), t.id))


def render(tasks):
    return "\n".join("%d [%s] %s" % (t.id, "x" if t.done else " ", t.text) for t in ordered(tasks))

